// The ops scaffolds `denext generate migration | seed | ci` emit — the same shape as
// `generate docker` (`docker-template.ts`): project-root files, the flavor auto-detected from
// the project with an optional override in the name slot, every file headed by a sentinel
// comment so a later tool can tell a generated file from a hand-written one, and nothing
// written over an existing file (that rule lives in `generate.ts`).
//
// - `migration <name>` writes `migrations/<UTC timestamp>_<name>.sql` and, the first time,
//   `jobs/migrate.ts`: a `defineJob` that applies every pending file in order on Deno's
//   built-in `node:sqlite`, recording each in a `_migrations` table (`denext job migrate`) —
//   or, when `DATABASE_URL` is a `postgres://` URL, on Postgres through `migratePostgres`. A
//   project that uses Postgres (that URL in the environment or `.env`, or a `postgres:` key in
//   its denext config) gets Postgres SQL in the new file. A Prisma or Drizzle project is pointed
//   at its own migration tool instead.
// - `seed [name]` writes `jobs/seed.ts` (`denext job seed`): a `node:sqlite` seed by
//   default, a `PrismaClient` one in a Prisma project.
// - `ci` writes `.github/workflows/ci.yml`: Deno pinned to the version generating it, then the
//   project's own `check` task (else `deno fmt --check`, `deno lint`, `deno test`) and its
//   `build` (or, for a SPA, `export`) task.
//
// Build-time only; never imported by a shipped bundle.

import { parse as parseJsonc } from "@std/jsonc";
import { join } from "@std/path";
import { detectDockerMode } from "./docker-template.ts";

/** One file an ops scaffold would write. */
export interface OpsPlanFile {
  /** Absolute path. */
  readonly path: string;
  /** Full contents. */
  readonly contents: string;
}

/** The ORM a project's migrations and seeds belong to. */
type DataFlavor = "sqlite" | "prisma" | "drizzle";

/** The sentinel line a generated file of `kind` opens with (`//` or `#` comment style). */
function sentinel(kind: "migration" | "seed" | "ci", comment: "//" | "--" | "#"): string {
  return `${comment} Generated by \`denext generate ${kind}\``;
}

async function exists(path: string): Promise<boolean> {
  try {
    await Deno.stat(path);
    return true;
  } catch {
    return false;
  }
}

/**
 * Detect the project's data layer: Prisma (`prisma/schema.prisma`), Drizzle
 * (`drizzle.config.*`), else plain `node:sqlite`. An explicit `sqlite` | `prisma` | `drizzle`
 * override wins.
 *
 * @param projectDir The project root.
 * @param override The name-slot override, if any.
 * @returns The flavor.
 */
async function detectDataFlavor(
  projectDir: string,
  override?: string,
): Promise<DataFlavor> {
  const o = (override ?? "").trim().toLowerCase();
  if (o === "sqlite" || o === "prisma" || o === "drizzle") return o;
  if (await exists(join(projectDir, "prisma", "schema.prisma"))) return "prisma";
  for (const ext of ["ts", "js", "mjs", "json"]) {
    if (await exists(join(projectDir, `drizzle.config.${ext}`))) return "drizzle";
  }
  return "sqlite";
}

/** A migration/seed name as a file-safe slug (`Add users` → `add_users`). */
export function slugName(name: string): string {
  return name.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
}

/** `20261007T093000` → `20261007093000`: the UTC timestamp a migration file is ordered by. */
function migrationStamp(now: Date): string {
  return now.toISOString().replace(/[-:T]/g, "").slice(0, 14);
}

/** The SQL file one migration starts as, in the project's dialect. */
function migrationSql(slug: string, postgres: boolean): string {
  const example = postgres
    ? `CREATE TABLE IF NOT EXISTS example (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);`
    : `CREATE TABLE IF NOT EXISTS example (
  id INTEGER PRIMARY KEY,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);`;
  const transaction = postgres
    ? "-- Write forward-only SQL; each file runs once, inside a transaction of its own (so no\n" +
      "-- BEGIN / COMMIT here)."
    : "-- Write forward-only SQL; each file runs once, inside a transaction (one that begins and commits\n" +
      "-- its own transaction runs as written).";
  return `${sentinel("migration", "--")} — applied in file-name order by \`denext job migrate\`.
${transaction}

-- ${slug}
${example}
`;
}

/** A `postgres://` / `postgresql://` URL. */
const POSTGRES_URL = /^\s*postgres(?:ql)?:\/\//i;

/** `DATABASE_URL=…` in a dotenv file, quoted or not. */
const DOTENV_DATABASE_URL = /^\s*(?:export\s+)?DATABASE_URL\s*=\s*["']?postgres(?:ql)?:\/\//im;

/**
 * Whether the project uses Postgres: `DATABASE_URL` is a `postgres://` URL (in the environment,
 * `.env` or `.env.local`), or its denext config has a `postgres:` key (`backend({ postgres })`).
 *
 * @param projectDir The project root.
 * @returns True for a Postgres project.
 */
export async function usesPostgres(projectDir: string): Promise<boolean> {
  let env: string | undefined;
  try {
    env = Deno.env.get("DATABASE_URL");
  } catch { /* no env permission: the files below still decide */ }
  if (env && POSTGRES_URL.test(env)) return true;
  for (const name of [".env", ".env.local"]) {
    const text = await readText(join(projectDir, name));
    if (text && DOTENV_DATABASE_URL.test(text)) return true;
  }
  for (const ext of ["ts", "js", "mjs", "mts"]) {
    const text = await readText(join(projectDir, `denext.config.${ext}`));
    if (text && /\bpostgres\s*:/.test(text)) return true;
  }
  return false;
}

/** A file's text, or `undefined` when it can't be read. */
async function readText(path: string): Promise<string | undefined> {
  try {
    return await Deno.readTextFile(path);
  } catch {
    return undefined;
  }
}

/**
 * `jobs/migrate.ts`: applies pending `migrations/*.sql` on Postgres when `DATABASE_URL` is a
 * `postgres://` URL, else on `node:sqlite`. `{ "dryRun": true }` / `{ "status": true }` as the
 * payload list instead of applying.
 */
const MIGRATE_JOB = `${sentinel("migration", "//")} — run it with \`denext job migrate\`.
//
// Applies every \`migrations/*.sql\` not yet recorded in the \`_migrations\` table, in file-name
// order, each inside its own transaction. \`denext job migrate --payload '{"dryRun":true}'\`
// lists what would run; \`--payload '{"status":true}'\` shows what ran.
//
// Postgres when DATABASE_URL is a postgres:// URL: migratePostgres takes an advisory lock, so two
// instances deploying at once never apply a migration twice. postgresClient() uses Deno.SQL, the
// Postgres client built into denext's Deno runtime; on stock Deno use the npm \`postgres\` package
// instead: \`fromPostgresJs(postgres(url))\` (import postgres from "npm:postgres").
//
// SQLite otherwise, on Deno's built-in node:sqlite (no npm). A file that manages its own
// transaction (a \`BEGIN;\` / \`COMMIT;\` statement) runs as written: SQLite can't nest one inside
// ours. DB_PATH picks the database file (default app.db) — the same one lib/db.ts opens.
import { DatabaseSync } from "node:sqlite";
import {
  defineJob,
  isPostgresUrl,
  migratePostgres,
  postgresClient,
  postgresMigrationStatus,
} from "denext/server";

const DIR = new URL("../migrations/", import.meta.url);
// A transaction statement of the file's own (a trigger's BEGIN … END; body is not one).
const OWN_TRANSACTION =
  /^\\s*(?:BEGIN(?:\\s+(?:DEFERRED|IMMEDIATE|EXCLUSIVE))?(?:\\s+TRANSACTION)?|COMMIT(?:\\s+TRANSACTION)?|END\\s+TRANSACTION)\\s*;/im;

/** What to do instead of applying: list pending (\`dryRun\`) or everything (\`status\`). */
interface MigratePayload {
  dryRun?: boolean;
  status?: boolean;
}

export default defineJob({
  description: "Apply pending SQL migrations",
  handler: async ({ payload }) => {
    const options = (payload ?? {}) as MigratePayload;
    const url = Deno.env.get("DATABASE_URL");
    if (url && isPostgresUrl(url)) return await onPostgres(url, options);
    return await onSqlite(options);
  },
});

async function onPostgres(
  url: string,
  options: MigratePayload,
): Promise<string> {
  const sql = postgresClient(url);
  try {
    if (options.status) {
      const status = await postgresMigrationStatus(sql, { dir: DIR });
      return status.migrations
        .map((m) =>
          \`\${m.applied ? "applied" : "pending"}  \${m.name}\${
            m.changed ? "  (changed)" : ""
          }\`
        )
        .concat(status.unknown.map((name) => \`unknown  \${name}\`))
        .join("\\n") || "no migrations";
    }
    const result = await migratePostgres(sql, {
      dir: DIR,
      dryRun: options.dryRun === true,
    });
    if (result.dryRun) {
      return result.pending.length
        ? \`would apply \${result.pending.join(", ")}\`
        : "up to date";
    }
    return result.applied.length
      ? \`applied \${result.applied.join(", ")}\`
      : "up to date";
  } finally {
    await sql.close();
  }
}

async function onSqlite(options: MigratePayload): Promise<string> {
  const db = new DatabaseSync(Deno.env.get("DB_PATH") ?? "app.db");
  try {
    db.exec(
      "CREATE TABLE IF NOT EXISTS _migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL)",
    );
    const done = new Set(
      db.prepare("SELECT name FROM _migrations").all().map((r) =>
        String(r.name)
      ),
    );
    const files: string[] = [];
    for await (const entry of Deno.readDir(DIR)) {
      if (entry.isFile && entry.name.endsWith(".sql")) files.push(entry.name);
    }
    const pending = files.sort().filter((name) => !done.has(name));
    if (options.status) {
      return files.map((name) =>
        \`\${done.has(name) ? "applied" : "pending"}  \${name}\`
      )
        .join("\\n") || "no migrations";
    }
    if (options.dryRun) {
      return pending.length
        ? \`would apply \${pending.join(", ")}\`
        : "up to date";
    }
    for (const name of pending) {
      // Encoded: a \`#\`, \`?\` or \`%\` in a file name is part of the name, not URL syntax.
      const sql = await Deno.readTextFile(
        new URL(encodeURIComponent(name), DIR),
      );
      const own = OWN_TRANSACTION.test(sql);
      if (!own) db.exec("BEGIN");
      try {
        db.exec(sql);
        db.prepare("INSERT INTO _migrations (name, applied_at) VALUES (?, ?)")
          .run(name, new Date().toISOString());
        if (!own) db.exec("COMMIT");
      } catch (err) {
        try {
          db.exec("ROLLBACK");
        } catch { /* the file's own transaction already ended */ }
        throw new Error(\`migration \${name} failed: \${(err as Error).message}\`);
      }
    }
    return pending.length ? \`applied \${pending.join(", ")}\` : "up to date";
  } finally {
    db.close();
  }
}
`;

/**
 * The files `denext generate migration <name>` writes: the timestamped SQL file (Postgres SQL
 * in a project that uses Postgres), plus the `jobs/migrate.ts` runner — Postgres or
 * `node:sqlite`, chosen by `DATABASE_URL` when it runs — when the project has none.
 *
 * @param projectDir The project root.
 * @param name The migration's name (`add_users`).
 * @param now The clock (tests pin it).
 * @returns The files, in write order.
 * @throws For a Prisma or Drizzle project (their own tools own migrations), or an empty name.
 */
export async function migrationPlan(
  projectDir: string,
  name: string,
  now: Date = new Date(),
): Promise<OpsPlanFile[]> {
  const flavor = await detectDataFlavor(projectDir);
  if (flavor === "prisma") {
    throw new Error(
      "denext: this is a Prisma project — create migrations with `prisma migrate dev --name " +
        `${slugName(name) || "<name>"}\` (denext runs \`prisma migrate deploy\` on its own).`,
    );
  }
  if (flavor === "drizzle") {
    throw new Error(
      "denext: this is a Drizzle project — create migrations with `drizzle-kit generate`.",
    );
  }
  const slug = slugName(name);
  if (!slug) throw new Error(`denext: migration name "${name}" has no letters or digits.`);
  const plan: OpsPlanFile[] = [{
    path: join(projectDir, "migrations", `${migrationStamp(now)}_${slug}.sql`),
    contents: migrationSql(slug, await usesPostgres(projectDir)),
  }];
  const runner = join(projectDir, "jobs", "migrate.ts");
  if (!(await exists(runner))) plan.push({ path: runner, contents: MIGRATE_JOB });
  return plan;
}

/** `jobs/seed.ts` on `node:sqlite`. */
function sqliteSeed(): string {
  return `${sentinel("seed", "//")} — run it with \`denext job seed\`.
//
// Inserts development data. Keep it idempotent (INSERT OR IGNORE / upserts) so it can run
// again; run \`denext job migrate\` first so the tables exist.
import { DatabaseSync } from "node:sqlite";
import { defineJob } from "denext/server";

export default defineJob({
  description: "Seed the database with development data",
  handler: () => {
    const db = new DatabaseSync(Deno.env.get("DB_PATH") ?? "app.db");
    try {
      const insert = db.prepare("INSERT OR IGNORE INTO example (id) VALUES (?)");
      db.exec("BEGIN");
      for (const id of [1, 2, 3]) insert.run(id);
      db.exec("COMMIT");
      return "seeded";
    } finally {
      db.close();
    }
  },
});
`;
}

/** `jobs/seed.ts` through the project's `PrismaClient`. */
function prismaSeed(): string {
  return `${sentinel("seed", "//")} — run it with \`denext job seed\`.
//
// Inserts development data through Prisma. Keep it idempotent (upsert) so it can run again.
import { PrismaClient } from "@prisma/client";
import { defineJob } from "denext/server";

export default defineJob({
  description: "Seed the database with development data",
  handler: async () => {
    const prisma = new PrismaClient();
    try {
      // await prisma.user.upsert({ where: { email: "ada@example.com" }, update: {},
      //   create: { email: "ada@example.com", name: "Ada" } });
      return "seeded";
    } finally {
      await prisma.$disconnect();
    }
  },
});
`;
}

/**
 * The file `denext generate seed [flavor]` writes: `jobs/seed.ts` for the detected data layer
 * (`sqlite` | `prisma`; Drizzle gets the `node:sqlite` shape to adapt).
 *
 * @param projectDir The project root.
 * @param override `sqlite` | `prisma` | `drizzle`, or empty to detect.
 * @returns The file.
 */
export async function seedPlan(projectDir: string, override?: string): Promise<OpsPlanFile[]> {
  const o = (override ?? "").trim().toLowerCase();
  if (o && o !== "seed" && !["sqlite", "prisma", "drizzle"].includes(o)) {
    throw new Error(`denext: unknown seed flavor "${override}" (expected: sqlite | prisma).`);
  }
  const flavor = await detectDataFlavor(projectDir, o);
  return [{
    path: join(projectDir, "jobs", "seed.ts"),
    contents: flavor === "prisma" ? prismaSeed() : sqliteSeed(),
  }];
}

/** The project's `deno.json` / `deno.jsonc` task names (empty when there is none). */
async function taskNames(projectDir: string): Promise<Set<string>> {
  for (const file of ["deno.json", "deno.jsonc"]) {
    let text: string;
    try {
      text = await Deno.readTextFile(join(projectDir, file));
    } catch {
      continue; // try the next
    }
    try {
      // Parsed, not pattern-matched: a task written as `{ "command": …, "dependencies": … }`
      // (or any `}` in a command) would end a regex's match early and hide the tasks after it.
      const tasks = (parseJsonc(text) as { tasks?: unknown } | null)?.tasks;
      return new Set(tasks && typeof tasks === "object" ? Object.keys(tasks) : []);
    } catch {
      return new Set(); // unparseable: no tasks known
    }
  }
  return new Set();
}

/** The workflow's check steps: the project's `check` task, else fmt + lint + test. */
function checkSteps(tasks: Set<string>): string {
  if (tasks.has("check")) return "      - run: deno task check\n";
  return "      - run: deno fmt --check\n      - run: deno lint\n" +
    (tasks.has("test") ? "      - run: deno task test\n" : "      - run: deno test -A\n");
}

/**
 * The file `denext generate ci [github]` writes: `.github/workflows/ci.yml`.
 *
 * @param projectDir The project root.
 * @param override `github` (the only provider), or empty.
 * @returns The file.
 */
export async function ciPlan(projectDir: string, override?: string): Promise<OpsPlanFile[]> {
  const o = (override ?? "").trim().toLowerCase();
  if (o && o !== "ci" && o !== "github") {
    throw new Error(`denext: unknown CI provider "${override}" (expected: github).`);
  }
  const tasks = await taskNames(projectDir);
  const spa = (await detectDockerMode(projectDir)) === "static";
  const buildTask = spa && tasks.has("export") ? "export" : tasks.has("build") ? "build" : null;
  const contents = `${sentinel("ci", "#")} — Deno pinned to the version that generated it;
# bump it deliberately.
name: CI

on:
  push:
    branches: [main]
  pull_request:

permissions:
  contents: read

jobs:
  check:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: denoland/setup-deno@v2
        with:
          deno-version: v${Deno.version.deno}
          cache: true
${checkSteps(tasks)}${buildTask ? `      - run: deno task ${buildTask}\n` : ""}`;
  return [{ path: join(projectDir, ".github", "workflows", "ci.yml"), contents }];
}
